create or replace function switch_dbuser() RETURNS void as $$
declare
    name text;
begin
	select into name 10::regrole;
    execute format('set role %s;', name);
	return;
end; $$ language plpgsql;
/

set ivorysql.compatible_mode to pg;
select switch_dbuser();

create database nlssort_gb18030 encoding='gb18030' LC_COLLATE='C' LC_CTYPE='C' TEMPLATE=template0;
\c nlssort_gb18030
LOAD 'gb18030_2022';

set ivorysql.compatible_mode to oracle;
set role system;

SET client_encoding=GB18030;

CREATE TABLE nlssort_gb18030 (id serial, val varchar(8));


select id, val, nlssort(val, 'nls_sort=binary')             from nlssort_gb18030 order by nlssort(val, 'nls_sort=binary'), id;
select id, val, nlssort(val, 'nls_sort=generic_m_ci')       from nlssort_gb18030 order by nlssort(val, 'nls_sort=generic_m_ci'), id;
select id, val, nlssort(val, 'nls_sort=schinese_pinyin_m')  from nlssort_gb18030 order by nlssort(val, 'nls_sort=schinese_pinyin_m'), id;
select id, val, nlssort(val, 'nls_sort=schinese_stroke_m')  from nlssort_gb18030 order by nlssort(val, 'nls_sort=schinese_stroke_m'), id;
select id, val, nlssort(val, 'nls_sort=schinese_radical_m') from nlssort_gb18030 order by nlssort(val, 'nls_sort=schinese_radical_m'), id;
select id, val, nlssort(val, 'nls_sort=uca0700_schinese')   from nlssort_gb18030 order by nlssort(val, 'nls_sort=uca0700_schinese'), id;
select id, val, nlssort(val, 'nls_sort=uca0700_schinese1')  from nlssort_gb18030 order by nlssort(val, 'nls_sort=uca0700_schinese1'), id;
select id, val, nlssort(val, 'nls_sort=uca0700_schinese2')  from nlssort_gb18030 order by nlssort(val, 'nls_sort=uca0700_schinese2'), id;

select id, val, nlssort(val, 'nls_sort=binary')             from nlssort_gb18030 order by val collate binary, id;
select id, val, nlssort(val, 'nls_sort=generic_m_ci')       from nlssort_gb18030 order by val collate generic_m_ci, id;
select id, val, nlssort(val, 'nls_sort=schinese_pinyin_m')  from nlssort_gb18030 order by val collate schinese_pinyin_m, id;
select id, val, nlssort(val, 'nls_sort=schinese_stroke_m')  from nlssort_gb18030 order by val collate schinese_stroke_m, id;
select id, val, nlssort(val, 'nls_sort=schinese_radical_m') from nlssort_gb18030 order by val collate schinese_radical_m, id;
select id, val, nlssort(val, 'nls_sort=uca0700_schinese')   from nlssort_gb18030 order by val collate uca0700_schinese, id;
select id, val, nlssort(val, 'nls_sort=uca0700_schinese1')  from nlssort_gb18030 order by val collate uca0700_schinese1, id;
select id, val, nlssort(val, 'nls_sort=uca0700_schinese2')  from nlssort_gb18030 order by val collate uca0700_schinese2, id;
